package com.cache.distributed

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.locks.ReentrantReadWriteLock
import kotlin.concurrent.read
import kotlin.concurrent.write

data class CacheEntry(
    val key: String,
    val value: ByteArray,
    val ttlMs: Long,
    val createdAt: Long = System.currentTimeMillis()
) {
    fun isExpired(): Boolean = System.currentTimeMillis() - createdAt > ttlMs
}

interface CacheNodeConnection {
    fun get(key: String): ByteArray?
    fun put(key: String, value: ByteArray, ttlMs: Long)
    fun close()
    fun isActive(): Boolean
}

class CacheNodeConnectionImpl(private val nodeId: String) : CacheNodeConnection {
    private val store = ConcurrentHashMap<String, CacheEntry>()
    private val active = AtomicBoolean(true)

    override fun get(key: String): ByteArray? {
        if (!active.get()) throw IllegalStateException("Connection closed for node $nodeId")
        val entry = store[key] ?: return null
        return if (entry.isExpired()) { store.remove(key); null } else entry.value
    }

    override fun put(key: String, value: ByteArray, ttlMs: Long) {
        if (!active.get()) throw IllegalStateException("Connection closed for node $nodeId")
        store[key] = CacheEntry(key, value, ttlMs)
    }

    override fun close() {
        active.set(false)
        store.clear()
    }

    override fun isActive(): Boolean = active.get()
}

class ConnectionPool(private val maxSize: Int = 8) {
    private val pool = ConcurrentHashMap<String, MutableList<CacheNodeConnection>>()
    private val lock = ReentrantReadWriteLock()

    fun acquire(nodeId: String): CacheNodeConnection {
        lock.read {
            val connections = pool.getOrPut(nodeId) { mutableListOf() }
            synchronized(connections) {
                val conn = connections.removeLastOrNull()
                if (conn != null && conn.isActive()) return conn
            }
        }
        return CacheNodeConnectionImpl(nodeId)
    }

    fun release(nodeId: String, connection: CacheNodeConnection) {
        lock.read {
            val connections = pool.getOrPut(nodeId) { mutableListOf() }
            synchronized(connections) {
                if (connections.size < maxSize && connection.isActive()) {
                    connections.add(connection)
                } else {
                    connection.close()
                }
            }
        }
    }

    fun evictNode(nodeId: String) {
        lock.write {
            pool.remove(nodeId)?.forEach { it.close() }
        }
    }
}

class DistributedCacheClient(
    private val nodes: List<String>,
    private val replicationFactor: Int = System.getenv("CACHE_REPLICATION_FACTOR")?.toIntOrNull() ?: 2,
    private val failoverEnabled: Boolean = System.getenv("CACHE_FAILOVER_ENABLED")?.toBoolean() ?: true
) {
    private val connectionPool = ConnectionPool()
    private val nodeStatus = ConcurrentHashMap<String, AtomicBoolean>()
    private val pendingOps = ConcurrentHashMap<String, CacheNodeConnection>()

    init {
        nodes.forEach { nodeStatus[it] = AtomicBoolean(true) }
    }

    private fun hashToNode(key: String): String {
        val hash = key.hashCode().toUInt()
        val activeNodes = nodes.filter { nodeStatus[it]?.get() == true }
        if (activeNodes.isEmpty()) throw IllegalStateException("No active nodes")
        return activeNodes[(hash % activeNodes.size.toUInt()).toInt()]
    }

    private fun getReplicaNodes(primaryNode: String): List<String> {
        val idx = nodes.indexOf(primaryNode)
        return (1 until replicationFactor).map { offset ->
            nodes[(idx + offset) % nodes.size]
        }.filter { nodeStatus[it]?.get() == true }
    }

    fun get(key: String): ByteArray? {
        val primaryNode = hashToNode(key)
        val conn = connectionPool.acquire(primaryNode)
        pendingOps[key] = conn

        return try {
            val result = conn.get(key)
            if (result == null && failoverEnabled) {
                connectionPool.release(primaryNode, conn)
                pendingOps.remove(key)
                return tryReplicaGet(key, primaryNode)
            }
            result
        } catch (e: Exception) {
            if (failoverEnabled) {
                handleNodeFailure(primaryNode)
                return tryReplicaGet(key, primaryNode)
            }
            null
        } finally {
            val pending = pendingOps.remove(key)
            if (pending != null) {
                connectionPool.release(primaryNode, pending)
            }
        }
    }

    private fun tryReplicaGet(key: String, failedNode: String): ByteArray? {
        val replicas = getReplicaNodes(failedNode)
        for (replica in replicas) {
            val conn = connectionPool.acquire(replica)
            try {
                return conn.get(key)
            } catch (e: Exception) {
                continue
            } finally {
                connectionPool.release(replica, conn)
            }
        }
        return null
    }

    fun put(key: String, value: ByteArray, ttlMs: Long = 60000) {
        val primaryNode = hashToNode(key)
        val conn = connectionPool.acquire(primaryNode)
        try {
            conn.put(key, value, ttlMs)
        } finally {
            connectionPool.release(primaryNode, conn)
        }

        if (replicationFactor > 1) {
            replicateAsync(key, value, ttlMs, primaryNode)
        }
    }

    private fun replicateAsync(key: String, value: ByteArray, ttlMs: Long, primaryNode: String) {
        val replicas = getReplicaNodes(primaryNode)
        for (replica in replicas) {
            val conn = connectionPool.acquire(replica)
            try {
                conn.put(key, value, ttlMs)
            } finally {
                connectionPool.release(replica, conn)
            }
        }
    }

    private fun handleNodeFailure(nodeId: String) {
        nodeStatus[nodeId]?.set(false)
        connectionPool.evictNode(nodeId)
    }

    fun close() {
        nodes.forEach { connectionPool.evictNode(it) }
    }
}
